import React, { useState, useEffect } from "react";
import api from "../services/api";
import "./ServiceStatusWidget.css"; // Ensure CSS styling

const ServiceStatusWidget = () => {
    const [webServices, setWebServices] = useState([]);
    const [dbServices, setDbServices] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchServiceStatus = async () => {
        try {
            const token = localStorage.getItem("token");
            if (!token) return;

            const response = await api.get("/api/auth/metrics/", {
                headers: { Authorization: `Token ${token}` },
            });

            console.log("Fetched API Response:", response.data);

            if (Array.isArray(response.data) && response.data.length > 0) {
                const metric = response.data[0];

                const parsedWebServices = JSON.parse(metric.web_service_status || "{}");
                const parsedDbServices = JSON.parse(metric.db_service_logs || "{}");

                // Define known database services
                const dbServiceNames = ["mysql", "postgresql"];

                // Filter only installed web services (excluding "not installed" and database services)
                const installedWebServices = Object.entries(parsedWebServices)
                    .filter(([service, status]) => status !== "not installed" && !dbServiceNames.includes(service))
                    .map(([service, status]) => ({ name: service, status }));

                // Filter only installed database services (excluding "not installed")
                const installedDbServices = Object.entries(parsedWebServices)
                    .filter(([service, status]) => status !== "not installed" && dbServiceNames.includes(service))
                    .map(([service, status]) => ({ name: service, status }));

                setWebServices(installedWebServices);
                setDbServices(installedDbServices);
            }
            setLoading(false);
        } catch (error) {
            console.error("Error fetching service status:", error);
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchServiceStatus();
        const interval = setInterval(fetchServiceStatus, 10000);
        return () => clearInterval(interval);
    }, []);

    return (
        <div className="widget service-status-widget">
            <h3>Service Status</h3>
            {loading ? <p>Loading...</p> : (
                <>
                    {webServices.length > 0 && (
                        <div>
                            <strong>Web Services:</strong>
                            <ul>
                                {webServices.map((service, index) => (
                                    <li key={index}>{service.name}: {service.status}</li>
                                ))}
                            </ul>
                        </div>
                    )}
                    {dbServices.length > 0 && (
                        <div>
                            <strong>Database Services:</strong>
                            <ul>
                                {dbServices.map((service, index) => (
                                    <li key={index}>{service.name}: {service.status}</li>
                                ))}
                            </ul>
                        </div>
                    )}
                    {webServices.length === 0 && dbServices.length === 0 && (
                        <p>No Installed Services Found</p>
                    )}
                </>
            )}
        </div>
    );
};

export default ServiceStatusWidget;
